package com.smartmanager.nativeapp;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;

/** Dedicated voucher page. Writes are confirmed and partial results remain visible in memory. */
public final class CardsActivity extends Activity {
 private LinearLayout page; private EditText prefix,count,profile; private Spinner backend; private TextView status,output; private final ExecutorService worker=Executors.newSingleThreadExecutor(); private final ArrayList<String[]> cards=new ArrayList<>(); private BatchStore journal; private String activeBatchId="current"; private boolean running; private static final int PDF=91;
 @Override public void onCreate(Bundle b){super.onCreate(b);journal=new BatchStore(this);ScrollView s=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(20,24,20,36);page.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);page.setBackgroundColor(Color.rgb(237,244,250));s.addView(page);setContentView(s); title(); form(); restore(); UiTheme.apply(this);}
 private void title(){TextView t=new TextView(this);t.setText("الكروت والدفعات");t.setTextSize(24);t.setTextColor(Color.rgb(15,36,66));t.setPadding(4,4,4,18);page.addView(t);status=text("جاهز - اختر الباقة من الراوتر",14);page.addView(status);output=text("لا توجد دفعة في الذاكرة",14);output.setTextIsSelectable(true);page.addView(output);}
 private void form(){backend=new Spinner(this);backend.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Hotspot","User Manager v6","User Manager v7"}));page.addView(backend);prefix=field("بادئة الكرت","SM");count=field("عدد الكروت (1-50)","1");profile=field("اسم الباقة الموجودة على الراوتر","");button("تحميل الباقات المتاحة",this::loadProfiles);button("إنشاء بعد التأكيد",()->{if(valid())new AlertDialog.Builder(this).setTitle("تأكيد إنشاء الدفعة").setMessage("سيتم إنشاء الكروت على الراوتر مباشرة. لا تعِد العملية عند انقطاع الاتصال قبل مراجعة القائمة.").setNegativeButton("إلغاء",null).setPositiveButton("إنشاء",(d,w)->create());});button("قالب الطباعة",()->startActivity(new Intent(this,TemplateActivity.class)));button("فتح سجل الدفعات المشفر",()->startActivity(new Intent(this,BatchHistoryActivity.class)));button("عمليات الكروت",()->startActivity(new Intent(this,CardOperationsActivity.class)));button("الكروت المنتهية",()->startActivity(new Intent(this,ExpiredCardsActivity.class)));button("صيانة User Manager",()->startActivity(new Intent(this,UserManagerMaintenanceActivity.class)));button("مصالحة النتائج غير المؤكدة",this::reconcile);button("معاينة الدفعة",this::preview);button("اختيار دفعة وطباعة كروت محددة",()->startActivity(new Intent(this,ArchivePrintActivity.class)));button("تصدير PDF",this::exportPdf);}
 private void restore(){try{String raw=journal.loadBatch("current");for(String line:raw.split("\\n")){String[] c=line.split("\\|",-1);if(c.length==4)cards.add(new String[]{c[0],c[1],c[2]});}if(!cards.isEmpty()){status.setText("تمت استعادة الدفعة المحفوظة");preview();}}catch(Exception e){status.setText("تعذر استعادة الدفعة");}}
 private void reconcile(){if(cards.isEmpty()){status.setText("لا توجد نتائج للمصالحة");return;}run(()->{try{String expected=journal.loadBatch("identity");if(expected==null||expected.isEmpty())throw new java.io.IOException("دفعة قديمة بلا هوية جهاز موثوقة؛ راجعها يدويًا");try(RouterService r=connect()){String current=RouterIdentityResolver.resolve(r);if(!expected.equals(current))throw new java.io.IOException("هوية الراوتر مختلفة؛ تمت حماية السجل");List<Map<String,String>> users=new HotspotService(r).users();int found=0;for(String[] c:cards)for(Map<String,String> u:users)if(c[0].equals(u.get("name"))){found++;break;}final int f=found;ui(()->status.setText("تمت المصالحة الآمنة: "+f+" من "+cards.size()));}}catch(Exception e){ui(()->status.setText(e.getMessage()==null?"فشلت المصالحة":e.getMessage()));}});}
 private void persist(String state){StringBuilder b=new StringBuilder();synchronized(cards){for(String[] c:cards)b.append(c[0]).append('|').append(c[1]).append('|').append(c[2]).append('|').append(state).append('\n');}try{journal.saveBatch(activeBatchId,b.toString());journal.saveBatch("current",b.toString());}catch(Exception ignored){status.setText("تعذر حفظ تقدم الدفعة؛ لم تُحذف البيانات");}}
 private void loadProfiles(){run(()->{try(RouterService r=connect()){String selected=backend.getSelectedItem()==null?"Hotspot":backend.getSelectedItem().toString();String ver=selected.contains("v6")?"6.":selected.contains("v7")?"7.":"";List<Map<String,String>> ps=selected.startsWith("Hotspot")?new HotspotService(r).profiles():new UserManagerService(r).profiles(ver);StringBuilder b=new StringBuilder("الباقات المتاحة:\n");for(Map<String,String> x:ps)b.append(x.getOrDefault("name","")).append('\n');ui(()->output.setText(b.toString()));}catch(Exception e){ui(()->output.setText(safe(e)));}});}
 private void create(){if(running)return;activeBatchId="batch-"+System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8);running=true;status.setText("جاري التحقق والتنفيذ...");final String pre=prefix.getText().toString().trim(), prof=profile.getText().toString().trim();final int n=Integer.parseInt(count.getText().toString());final String selected=backend.getSelectedItem()==null?"Hotspot":backend.getSelectedItem().toString();final boolean um=!selected.startsWith("Hotspot");final String umVersion=selected.contains("v6")?"6.":"7.";run(()->{int confirmed=0;try(RouterService r=connect()){String identity=RouterIdentityResolver.resolve(r);journal.saveBatch("identity",identity);List<Map<String,String>> users=um?new UserManagerService(r).users(umVersion):new HotspotService(r).users();int serial=VoucherService.nextSerial(users,pre);synchronized(cards){cards.clear();}for(int i=0;i<n;i++){String name=pre+String.format(Locale.ROOT,"%07d",serial++);boolean exists=false;for(Map<String,String> row:users)if(name.equals(row.get("name")))exists=true;if(exists)continue;String pass=VoucherService.password();if(um)new UserManagerService(r).addUser(umVersion,name,pass,prof);else new HotspotService(r).addUser(name,pass,prof);synchronized(cards){cards.add(new String[]{name,pass,prof});}persist("CONFIRMED");confirmed++;}final int done=confirmed;ui(()->{running=false;status.setText("تم تأكيد "+done+" من "+n);preview();});}catch(java.io.IOException uncertain){persist("UNKNOWN");final int done=confirmed;ui(()->{running=false;status.setText("النتيجة غير مؤكدة");output.setText("تم تأكيد "+done+" كرت. تحقق من الراوتر قبل إعادة المحاولة.");});}catch(Exception e){ui(()->{running=false;status.setText("فشل الدفعة");output.setText(safe(e));});}});}
 private boolean valid(){try{int n=Integer.parseInt(count.getText().toString());if(n<1||n>50)throw new Exception();}catch(Exception e){status.setText("العدد يجب أن يكون بين 1 و50");return false;}if(!prefix.getText().toString().matches("[A-Za-z0-9_-]{1,20}")||profile.getText().toString().trim().isEmpty()){status.setText("تحقق من البادئة والباقة");return false;}return !running;}
 private void preview(){StringBuilder b=new StringBuilder("الكروت المؤكدة في هذه الجلسة:\n");synchronized(cards){for(String[] c:cards)b.append(c[0]).append(" | ").append(c[1]).append(" | ").append(c[2]).append('\n');}output.setText(b.toString());}
 private void exportPdf(){synchronized(cards){if(cards.isEmpty()){status.setText("لا توجد دفعة مؤكدة");return;}}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"smart-manager-vouchers.pdf");startActivityForResult(i,PDF);}
 @Override protected void onActivityResult(int r,int result,Intent d){super.onActivityResult(r,result,d);if(r==PDF&&result==RESULT_OK&&d!=null&&d.getData()!=null)try{PdfService.write(this,d.getData(),new ArrayList<>(cards));status.setText("تم تصدير PDF");}catch(Exception e){status.setText("فشل PDF");}}
 private RouterService connect()throws Exception{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pass="";try{String v=new SecureConnectionStore(this).get();if(v!=null)pass=v;}catch(Exception ignored){}RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false));r.login(p.getString("user",""),pass);return r;}
 private EditText field(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(true);page.addView(e);return e;}private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(23,103,177)));b.setOnClickListener(v->r.run());page.addView(b);}private TextView text(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(15,36,66));t.setPadding(8,10,8,10);return t;}private void run(Runnable r){worker.execute(r);}private void ui(Runnable r){runOnUiThread(r);}private String safe(Exception e){return e.getMessage()==null?"خطأ غير معروف":e.getMessage();}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
